const d = $input.first().json;
if (!d || d.schema !== "trivalley.global-intel.v1" ||
    !Array.isArray(d.source_health) || !Array.isArray(d.events) ||
    !Array.isArray(d.connections)) throw new Error("GLOBAL_INTEL_SCHEMA_INVALID");
const at = Date.parse(d.generated_at);
const age = Date.now() - at;
const validTime = Number.isFinite(at) && age >= -120000 && age < 8*60*60*1000;
const healthy = d.source_health.filter(s => s.state === "ok");
const families = [...new Set(healthy.map(s => String(s.name).split(" / ")[0]))];
const state = !validTime ? "BLOCKED_STALE" :
    families.length < 2 ? "DEGRADED_SOURCE_COVERAGE" :
    d.status === "OK" ? "READY_FOR_HUMAN_REVIEW" : "DEGRADED_SOURCE_COVERAGE";
return [{json:{
  schema:"trivalley-global-intel-chief-review-v1",
  observed_at:new Date().toISOString(),
  source_generated_at:d.generated_at || null,
  state,
  source_families:families,
  healthy_feeds:healthy.length,
  feed_count:d.source_health.length,
  indexed_signals:d.events.length,
  candidate_links:d.connections.length,
  attribution:"public GDELT + USGS + NASA EONET metadata",
  evidence_url:"https://2strongtrainers-art.github.io/Nicholas-AI-OS/data/events.json",
  github_source:"https://github.com/2strongtrainers-art/Nicholas-AI-OS/tree/main/intel-desk",
  chief_delivery:"NOT_SENT_MANUAL_REVIEW_REQUIRED",
  interpretation:"Cross-topic place mentions are investigative leads, not proof of causation",
  approval_state:"REVIEW_REQUIRED",
  outbound_actions:0,
  money_spent_usd:0
}}];
